// 在本程序集中按名称精确查找类型，用 DeclaredOnly 统计属性与方法

private.reference_solution:
using System.Reflection;

var name = (Console.ReadLine() ?? "").Trim();
var type = typeof(Plane).Assembly.GetTypes()
    .FirstOrDefault(candidate => candidate.Name == name);
if (type is null) Environment.Exit(1);
var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
    .Count(method => !method.IsSpecialName);
Console.WriteLine($"props={properties.Length} methods={methods}");

sealed class Plane
{
    public int Capacity { get; set; }
    public string Code { get; set; } = "";
    public int Fly(int distance) => distance * 2;
}

