using System.Globalization;
using System.Text.RegularExpressions;

// 解析并校验 -> 写入相对路径 receipt.txt -> 读回输出 -> 累加总价

private.reference_solution:
using System.Globalization;
using System.Text.RegularExpressions;

var first = Console.ReadLine();
var count = 0;
if (first is null || !int.TryParse(first.Trim(), out count) || count < 0 || count > 100)
{
    Environment.Exit(1);
}
var lines = new List<string>();
decimal total = 0;
for (var i = 0; i < count; i++)
{
    var tokens = (Console.ReadLine() ?? "").Split(' ');
    if (tokens.Length != 3 || tokens[0].Length == 0) Environment.Exit(1);
    if (!int.TryParse(tokens[1], out var quantity) || quantity < 1 || quantity > 99) Environment.Exit(1);
    if (!Regex.IsMatch(tokens[2], @"^\d{1,3}(\.\d{1,2})?$")) Environment.Exit(1);
    var price = decimal.Parse(tokens[2], CultureInfo.InvariantCulture);
    if (price <= 0) Environment.Exit(1);
    total += quantity * price;
    lines.Add($"{quantity} x {tokens[0]} @ {price.ToString("F2", CultureInfo.InvariantCulture)}");
}
File.WriteAllLines("receipt.txt", lines);
foreach (var stored in File.ReadAllLines("receipt.txt"))
{
    Console.WriteLine(stored);
}
Console.WriteLine("total=" + total.ToString("F2", CultureInfo.InvariantCulture));
